private open class MessagesPigeonCodec : StandardMessageCodec() {
  override fun readValueOfType(type: Byte, buffer: ByteBuffer): Any? {
    return when (type) {
      129.toByte() -> {
        return (readValue(buffer) as Long?)?.let {
          SignalKind.ofRaw(it.toInt())
        }
      }
      130.toByte() -> {
        return (readValue(buffer) as Long?)?.let {
          LeaseMode.ofRaw(it.toInt())
        }
      }
      131.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          PlatformSignal.fromList(it)
        }
      }
      132.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          MemorySample.fromList(it)
        }
      }
      133.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          ExitRecord.fromList(it)
        }
      }
      134.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          DeviceInfo.fromList(it)
        }
      }
      135.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          LeaseRequest.fromList(it)
        }
      }
      136.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          LeaseResult.fromList(it)
        }
      }
      else -> super.readValueOfType(type, buffer)
    }
  }
  override fun writeValue(stream: ByteArrayOutputStream, value: Any?)   {
    when (value) {
      is SignalKind -> {
        stream.write(129)
        writeValue(stream, value.raw.toLong())
      }
      is LeaseMode -> {
        stream.write(130)
        writeValue(stream, value.raw.toLong())
      }
      is PlatformSignal -> {
        stream.write(131)
        writeValue(stream, value.toList())
      }
      is MemorySample -> {
        stream.write(132)
        writeValue(stream, value.toList())
      }
      is ExitRecord -> {
        stream.write(133)
        writeValue(stream, value.toList())
      }
      is DeviceInfo -> {
        stream.write(134)
        writeValue(stream, value.toList())
      }
      is LeaseRequest -> {
        stream.write(135)
        writeValue(stream, value.toList())
      }
      is LeaseResult -> {
        stream.write(136)
        writeValue(stream, value.toList())
      }
